import{_ as t,a}from"./chunks/px4_sitl_overview.XgOTfz33.js";import{_ as i,o as s,c as n,al as o}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"仿真","description":"","frontmatter":{},"headers":[],"relativePath":"zh/simulation/index.md","filePath":"zh/simulation/index.md"}'),r={name:"zh/simulation/index.md"};function l(h,e,p,d,c,m){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="仿真" tabindex="-1">仿真 <a class="header-anchor" href="#仿真" aria-label="Permalink to &quot;仿真&quot;">​</a></h1><p>在仿真机中模拟器允许 px4 飞行代码来控制计算机建模工具。 You can interact with this vehicle just as you might with a real vehicle, using <em>QGroundControl</em>, an offboard API, or a radio controller/gamepad.</p><p>PX4 supports both <em>Software In the Loop (SITL)</em> simulation, where the flight stack runs on computer (either the same computer or another computer on the same network) and <em>Hardware In the Loop (HITL)</em> simulation using a simulation firmware on a real flight controller board.</p><p>Information about available simulators and how to set them up are provided in the next section. The other sections provide general information about how the simulator works, and are not required to <em>use</em> the simulators.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Simulation is a quick, easy, and most importantly, <em>safe</em> way to test changes to PX4 code before attempting to fly in the real world. It is also a good way to start flying with PX4 when you haven&#39;t yet got a vehicle to experiment with.</p></div><h2 id="支持的仿真器" tabindex="-1">支持的仿真器 <a class="header-anchor" href="#支持的仿真器" aria-label="Permalink to &quot;支持的仿真器&quot;">​</a></h2><p>The following simulators are supported by the PX4 core development team.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Gazebo Classic is being downgraded to <a href="./../simulation/community_supported_simulators">community supported</a> and is no longer recommended as the default simulation solution. Use <a href="./../sim_gazebo_gz/">Gazebo</a> (formerly Gazebo Ignition) for new projects. If you have an older workflow that does not yet work in newer Gazebo, Gazebo Classic remains available but will not receive core team maintenance going forward. See <a href="https://github.com/PX4/PX4-Autopilot/issues/23602" target="_blank" rel="noreferrer">PX4-Autopilot#23602</a> for the deprecation timeline and migration status.</p></div><table tabindex="0"><thead><tr><th>仿真器</th><th>描述</th></tr></thead><tbody><tr><td><a href="./../sim_gazebo_gz/">Gazebo</a></td><td>Gazebo supersedes <a href="./../sim_gazebo_classic/">Gazebo Classic</a>, featuring more advanced rendering, physics and sensor models. It is the only version of Gazebo available from Ubuntu Linux 22.04<br><br>A powerful 3D simulation environment that is particularly suitable for testing object-avoidance and computer vision. 它还可用于 <a href="./../simulation/multi-vehicle-simulation">多工具仿真</a>，通常用于 <a href="./../simulation/ros_interface">ROS</a>，这是一种用于自动控制的工具集。 <br><br><strong>Supported Vehicles:</strong> Quad, VTOL (Standard, Tailsitter, Tiltroter), Plane, Rovers</td></tr><tr><td><a href="./../sim_sih/">SIH</a></td><td>A lightweight, headless simulator that runs physics directly inside PX4 as a C++ module (no external dependencies). Headless by default for fastest iteration. Supports ROS 2 via uXRCE-DDS. Can also run on flight controller hardware (<code>SYS_HITL=2</code>).<br><br><strong>Supported Vehicles:</strong> Quad, Hex, Plane, Tailsitter, Standard VTOL, Rover</td></tr><tr><td><a href="./../sim_gazebo_classic/">Gazebo Classic</a></td><td>A powerful 3D simulation environment that is particularly suitable for testing object-avoidance and computer vision. It can also be used for <a href="./../simulation/multi-vehicle-simulation">multi-vehicle simulation</a> and is commonly used with <a href="./../simulation/ros_interface">ROS</a>, a collection of tools for automating vehicle control.<br><br><strong>Supported Vehicles:</strong> Quad (<a href="./../airframes/airframe_reference#copter_quadrotor_x_generic_quadcopter">Iris</a>), Hex (Typhoon H480), <a href="./../airframes/airframe_reference#vtol_standard_vtol_generic_standard_vtol">Generic Standard VTOL (QuadPlane)</a>, Tailsitter, Plane, Rover, Submarine</td></tr></tbody></table><p>There are also a number of <a href="./../simulation/community_supported_simulators">Community Supported Simulators</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To run PX4 SITL without setting up a build environment, <a href="./px4_sitl_prebuilt_packages">pre-built packages and containers</a> are available.</p></div><h3 id="simulator-comparison" tabindex="-1">Simulator Comparison <a class="header-anchor" href="#simulator-comparison" aria-label="Permalink to &quot;Simulator Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>Gazebo</th><th>SIH</th></tr></thead><tbody><tr><td><strong>Default Mode</strong></td><td>GUI with 3D rendering</td><td>Headless (fastest iteration)</td></tr><tr><td><strong>3D Visualization</strong></td><td>Built-in (photorealistic)</td><td>Optional: QGC map or jMAVSim display-only</td></tr><tr><td><strong>Physics Engine</strong></td><td>External (gz-physics)</td><td>Internal (C++ module, uORB)</td></tr><tr><td><strong>External Dependencies</strong></td><td>Gazebo packages, rendering libs</td><td>None</td></tr><tr><td><strong>Vehicle Types</strong></td><td>Quad, VTOL, Plane, Rovers</td><td>Quad, Hex, Plane, Tailsitter, Std VTOL, Rover</td></tr><tr><td><strong>Multi-vehicle</strong></td><td>Yes (documented)</td><td>Yes (<a href="./../sim_sih/#multi-vehicle-simulation">multi-vehicle</a>)</td></tr><tr><td><strong>Sensor Simulation</strong></td><td>Camera, LiDAR, depth, IMU, GPS, baro, mag</td><td>IMU, GPS, baro, mag, airspeed</td></tr><tr><td><strong>Custom Worlds/Models</strong></td><td>Yes (SDF, large model library)</td><td>No</td></tr><tr><td><strong>ROS 2 Integration</strong></td><td>Yes (uXRCE-DDS)</td><td>Yes (uXRCE-DDS)</td></tr><tr><td><strong>Extensibility</strong></td><td>Plugins, custom sensors, environments</td><td>Modify C++ source, tune SIH_* parameters</td></tr><tr><td><strong>Community/Ecosystem</strong></td><td>Large Gazebo community, model repos</td><td>PX4-internal</td></tr><tr><td><strong>Faster-than-Realtime</strong></td><td>Yes</td><td>Yes</td></tr><tr><td><strong>Runs on FC Hardware</strong></td><td>No</td><td>Yes (SYS_HITL=2)</td></tr><tr><td><strong>macOS Apple Silicon</strong></td><td>Unstable (known issues)</td><td>Works natively</td></tr><tr><td><strong>Lockstep</strong></td><td>Yes</td><td>Yes</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For a detailed analysis of PX4 simulation user needs, priorities, and pain points, see the <a href="https://www.mcguirerobotics.com/px4_sim_research_report/" target="_blank" rel="noreferrer">PX4 Simulation Integration Survey Report</a> (K. McGuire, Dronecode Foundation, Dec 2025, 120 respondents).</p></div><h3 id="which-simulator-should-i-use" tabindex="-1">Which Simulator Should I Use? <a class="header-anchor" href="#which-simulator-should-i-use" aria-label="Permalink to &quot;Which Simulator Should I Use?&quot;">​</a></h3><ul><li><strong>Full-featured simulation with 3D rendering, custom worlds, camera/lidar sensors, or rich sensor ecosystems:</strong> Use <a href="./../sim_gazebo_gz/">Gazebo</a>. Largest ecosystem, custom models and plugins, photorealistic rendering, extensive sensor library, large community.</li><li><strong>Fast headless iteration, controls research, zero-dependency setup, or macOS:</strong> Use <a href="./../sim_sih/">SIH</a>. Runs entirely inside PX4 with no external dependencies, headless by default for maximum speed, physics parameters directly tunable via <code>SIH_*</code> params. Supports ROS 2 via uXRCE-DDS.</li><li><strong>Hardware integration testing without propellers:</strong> Use <a href="./../sim_sih/#sih-on-flight-controller-hardware">SIH on flight controller hardware</a> (<code>SYS_HITL=2</code>).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>SIH is headless by default. For optional 3D visualization, you can use <a href="./../sim_sih/#visualization-optional">jMAVSim in display-only mode</a> or monitor the vehicle in QGroundControl&#39;s map view.</p></div><h2 id="仿真器-mavlink-api" tabindex="-1">仿真器 MAVLink API <a class="header-anchor" href="#仿真器-mavlink-api" aria-label="Permalink to &quot;仿真器 MAVLink API&quot;">​</a></h2><p>Most external simulators communicate with PX4 using the Simulator MAVLink API. This API defines a set of MAVLink messages that supply sensor data from the simulated world to PX4 and return motor and actuator values from the flight code that will be applied to the simulated vehicle. The image below shows the message flow.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>SIH does not use the MAVLink simulator API. It runs physics internally via uORB messages. Gazebo communicates with PX4 via gz_bridge (Gazebo transport), not MAVLink.</p></div><p><img src="'+t+'" alt="Simulator MAVLink API"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A SITL build of PX4 uses <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/simulation/simulator_mavlink/SimulatorMavlink.cpp" target="_blank" rel="noreferrer">SimulatorMavlink.cpp</a> to handle these messages while a hardware build in HIL mode uses <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/modules/mavlink/mavlink_receiver.cpp" target="_blank" rel="noreferrer">mavlink_receiver.cpp</a>. 这些端口是： All motors / actuators are blocked, but internal software is fully operational.</p></div><p>The messages are described below (see links for specific detail).</p><table tabindex="0"><thead><tr><th>消息</th><th>方向</th><th>描述</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_MODE_FLAG_HIL_ENABLED" target="_blank" rel="noreferrer">MAV_MODE:MAV_MODE_FLAG_HIL_ENABLED</a></td><td>不可用</td><td>使用模拟时的模式标志。 所有电机/执行器都被卡停，但内部软件可以完全正常运行。</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_ACTUATOR_CONTROLS" target="_blank" rel="noreferrer">HIL_ACTUATOR_CONTROLS</a></td><td>PX4 至 Sim</td><td>PX4 控制输出 （电机、执行器）。</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_SENSOR" target="_blank" rel="noreferrer">HIL_SENSOR</a></td><td>Sim 至 PX4</td><td>在 NED 体框架中以 SI 单位模拟 IMU 读数。</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_GPS" target="_blank" rel="noreferrer">HIL_GPS</a></td><td>Sim 至 PX4</td><td>模拟的 GPS RAW 传感器值。</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_OPTICAL_FLOW" target="_blank" rel="noreferrer">HIL_OPTICAL_FLOW</a></td><td>Sim 至 PX4</td><td>来自流量传感器的模拟光流 （例如 PX4FLOW 或光学鼠标传感器）。</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_STATE_QUATERNION" target="_blank" rel="noreferrer">HIL_STATE_QUATERNION</a></td><td>Sim 至 PX4</td><td>包含实际的“仿真”无人机位置、姿态、速度等。 这可以记录并与 px4 的分析和调试估计进行比较 （例如，检查估计器在噪声 （仿真） 传感器输入中的工作情况）。</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#HIL_RC_INPUTS_RAW" target="_blank" rel="noreferrer">HIL_RC_INPUTS_RAW</a></td><td>Sim 至 PX4</td><td>收到 RC 通道的 RAW 值。</td></tr></tbody></table><p>PX4 directly uses the <a href="https://gazebosim.org/docs/" target="_blank" rel="noreferrer">Gazebo API</a> to interface with <a href="./../sim_gazebo_gz/">Gazebo</a> and MAVlink is not required.</p><h2 id="默认-px4-mavlink-udp-端口" tabindex="-1">默认 PX4 MAVLink UDP 端口 <a class="header-anchor" href="#默认-px4-mavlink-udp-端口" aria-label="Permalink to &quot;默认 PX4 MAVLink UDP 端口&quot;">​</a></h2><p>By default, PX4 uses commonly established UDP ports for MAVLink communication with ground control stations (e.g. <em>QGroundControl</em>), Offboard APIs (e.g. MAVSDK, MAVROS) and simulator APIs (e.g. Gazebo). These ports are:</p><ul><li>PX4&#39;s remote UDP Port <strong>14550</strong> is used for communication with ground control stations. 期望 GCS 侦听此端口上的连接。 <em>QGroundControl</em> 默认侦听此端口。</li><li>PX4的远程UDP端口 <strong>14540</strong> 用于与 offboard API 通信。 期望 Offboard APIs 侦听此端口上的连接。<div class="info custom-block"><p class="custom-block-title">INFO</p><p>Multi-vehicle simulations use a separate remote port for each instance, allocated sequentially from <code>14540</code> to <code>14549</code> (additional instances all use port <code>14549</code>).</p></div></li></ul><p>:::</p><ul><li>The simulator&#39;s local TCP Port, <strong>4560</strong>, is used for communication with PX4. PX4 侦听此端口，仿真器应通过向该端口广播数据来启动通信。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The ports for the GCS, offboard APIs and simulator are specified by startup scripts. See <a href="./../concept/system_startup">System Startup</a> to learn more.</p></div><h2 id="sitl-仿真环境" tabindex="-1">SITL 仿真环境 <a class="header-anchor" href="#sitl-仿真环境" aria-label="Permalink to &quot;SITL 仿真环境&quot;">​</a></h2><p>The diagram below shows a typical SITL simulation environment for any of the supported simulators that use MAVLink (i.e. most external simulators, but not Gazebo or SIH).</p><p><img src="'+a+`" alt="PX4 SITL overview"></p><p>The different parts of the system connect via UDP, and can be run on either the same computer or another computer on the same network.</p><ul><li><p>PX4 uses a simulation-specific module to connect to the simulator&#39;s local TCP port 4560. Simulators then exchange information with PX4 using the <a href="#simulator-mavlink-api">Simulator MAVLink API</a> described above. SITL 和模拟器上的 PX4 可以在同一台计算机上运行，也可以在同一网络上运行不同的计算机。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Simulators can also use the <em>uxrce-dds bridge</em> (<a href="./../middleware/uxrce_dds">XRCE-DDS</a>) to directly interact with PX4 (i.e. via <a href="./../middleware/uorb">UORB topics</a> rather than MAVLink). This approach <em>may</em> used by Gazebo Classic for <a href="./../sim_gazebo_classic/multi_vehicle_simulation#build-and-test-xrce-dds">multi-vehicle simulation</a>.</p></div></li></ul><p>:::</p><ul><li><p>PX4 uses the normal MAVLink module to connect to ground stations and external developer APIs like MAVSDK or ROS</p><ul><li>Ground stations listen to PX4&#39;s remote UDP port: <code>14550</code></li><li>External developer APIs listen to PX4&#39;s remote UDP port: <code>14540</code>. For multi-vehicle simulations, PX4 sequentially allocates a separate remote port for each instance from <code>14540</code> to <code>14549</code> (additional instances all use port <code>14549</code>).</li></ul></li><li><p>PX4 defines a number of <em>local</em> UDP ports (<code>14580</code>,<code>18570</code>), which are sometimes used when networking with PX4 running in a container or virtual machine. These are not recommended for &quot;general&quot; use and may change in future.</p></li><li><p>A serial connection may be used to connect <a href="./../config/joystick">Joystick/Gamepad</a> hardware via <em>QGroundControl</em>.</p></li></ul><p>If you use the normal build system SITL <code>make</code> configuration targets (see next section) then both SITL and the Simulator will be launched on the same computer and the ports above will automatically be configured. You can configure additional MAVLink UDP connections and otherwise modify the simulation environment in the build configuration and initialisation files.</p><h3 id="启动-构建-sitl-模拟" tabindex="-1">启动/构建 SITL 模拟 <a class="header-anchor" href="#启动-构建-sitl-模拟" aria-label="Permalink to &quot;启动/构建 SITL 模拟&quot;">​</a></h3><p>The build system makes it very easy to build and start PX4 on SITL, launch a simulator, and connect them. The syntax (simplified) looks like this:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> simulator[_vehicle-model]</span></span></code></pre></div><p>where <code>simulator</code> is <code>gz</code> (for Gazebo), <code>gazebo-classic</code>, <code>jmavsim</code> or some other simulator, and vehicle-model is a particular vehicle type supported by that simulator (<a href="./../sim_gazebo_gz/">Gazebo</a> and <a href="./../sim_jmavsim/">jMAVSim</a> only support multicopters at time of writing, while <a href="./../sim_gazebo_classic/">Gazebo Classic</a> supports many different types).</p><p>A number of examples are shown below, and there are many more in the individual pages for each of the simulators:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start Gazebo with the x500 multicopter</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start Gazebo Classic with plane</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gazebo-classic_plane</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start Gazebo Classic with iris and optical flow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gazebo-classic_iris_opt_flow</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start JMavSim with iris (default vehicle model)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jmavsim</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start PX4 with no simulator (i.e. to use your own &quot;custom&quot; simulator)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none_iris</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SIH (headless, zero dependencies)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_quadx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_sih</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sihsim_airplane</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Use <code>px4_sitl_sih</code> instead of <code>px4_sitl</code> to avoid building Gazebo dependencies.</p></div><p>The simulation can be further configured via environment variables:</p><ul><li>Any of the <a href="./../advanced_config/parameter_reference">PX4 parameters</a> can be overridden via <code>export PX4_PARAM_{name}={value}</code>. For example changing the estimator: <code>export PX4_PARAM_EKF2_EN=0; export PX4_PARAM_ATT_EN=1</code>.</li></ul><p>The syntax described here is simplified, and there are many other options that you can configure via <em>make</em> - for example, to set that you wish to connect to an IDE or debugger. For more information see: <a href="./../dev_setup/building_px4#px4-make-build-targets">Building the Code &gt; PX4 Make Build Targets</a>.</p><h3 id="simulation_speed" tabindex="-1">Run Simulation Faster than Realtime <a class="header-anchor" href="#simulation_speed" aria-label="Permalink to &quot;Run Simulation Faster than Realtime {#simulation_speed}&quot;">​</a></h3><p>SITL can be run faster or slower than real-time when using Gazebo, Gazebo Classic, jMAVSim, or SIH.</p><p>The speed factor is set using the environment variable <code>PX4_SIM_SPEED_FACTOR</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 SITL and the simulators are run in <em>lockstep</em>, which means that they are locked to run at the same speed, and therefore can react appropriately to sensor and actuator messages. This is what makes it possible to run the simulation at different speeds, and also pause the simulation in order to step through code.</p></div><p>有关详细信息，请参阅︰</p><ul><li>Gazebo: <a href="./../sim_gazebo_gz/#change-simulation-speed">Change Simulation Speed</a></li><li>Gazebo Classic: <a href="./../sim_gazebo_classic/#change-simulation-speed">Change Simulation Speed</a> and <a href="./../sim_gazebo_classic/#lockstep">Lockstep</a></li><li>jMAVSim: <a href="./../sim_jmavsim/#change-simulation-speed">Change Simulation Speed</a> and <a href="./../sim_jmavsim/#lockstep">Lockstep</a></li><li>SIH: Supports <code>PX4_SIM_SPEED_FACTOR</code> for faster-than-realtime simulation.</li></ul><h3 id="启动脚本" tabindex="-1">启动脚本 <a class="header-anchor" href="#启动脚本" aria-label="Permalink to &quot;启动脚本&quot;">​</a></h3><p>Scripts are used to control which parameter settings to use or which modules to start. They are located in the <a href="https://github.com/PX4/PX4-Autopilot/tree/main/ROMFS/px4fmu_common/init.d-posix" target="_blank" rel="noreferrer">ROMFS/px4fmu_common/init.d-posix</a> directory, the <code>rcS</code> file is the main entry point. See <a href="./../concept/system_startup">System Startup</a> for more information.</p><h3 id="simulating-failsafes-and-sensor-hardware-failure" tabindex="-1">Simulating Failsafes and Sensor/Hardware Failure <a class="header-anchor" href="#simulating-failsafes-and-sensor-hardware-failure" aria-label="Permalink to &quot;Simulating Failsafes and Sensor/Hardware Failure&quot;">​</a></h3><p><a href="./../simulation/failsafes">Simulate Failsafes</a> explains how to trigger safety failsafes like GPS failure and battery drain.</p><h3 id="environment-configuration" tabindex="-1">Environment Configuration <a class="header-anchor" href="#environment-configuration" aria-label="Permalink to &quot;Environment Configuration&quot;">​</a></h3><p>SITL simulation behaviour can be configured using the following environment variables. These can be specified inline, before the <code>make</code> command, or set for the environment using <code>export</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For Gazebo-specific environment variables (such as <code>PX4_GZ_WORLD</code>, <code>PX4_GZ_STANDALONE</code>, etc.), see <a href="./../sim_gazebo_gz/#usage-configuration-options">Gazebo &gt; Usage/Configuration Options</a>.</p></div><ul><li><p><code>PX4_SIM_SPEED_FACTOR</code>: Sets the speed factor to run the simulation at faster or slower than realtime. For example, to run Gazebo simulation at two times the speed factor:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_SIM_SPEED_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>For more information see <a href="#simulation_speed">Run Simulation Faster than Realtime</a>.</p></li><li><p><code>PX4_PARAM_{name}={value}</code>: Overrides any <a href="./../advanced_config/parameter_reference">PX4 parameter</a> for the simulation session. For example, to switch from EKF2 to the attitude estimator:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_PARAM_EKF2_EN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_PARAM_ATT_EN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div></li><li><p><code>PX4_NET_INTERFACE</code>: Binds all MAVLink connections to a specific network interface (e.g. <code>eth0</code>). This is useful when running simulations in containerized environments (e.g. Docker) or on systems with multiple network interfaces where you need MAVLink traffic to use a particular interface.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_NET_INTERFACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">eth0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>Or inline with the make command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_NET_INTERFACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eth0</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>This sets the <code>-n</code> flag on all <code>mavlink start</code> commands in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink" target="_blank" rel="noreferrer">/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink</a>, binding MAVLink to the specified interface. When <code>PX4_NET_INTERFACE</code> is not set, MAVLink binds to all interfaces (default behaviour).</p></li></ul><h2 id="hitl-仿真环境" tabindex="-1">HITL 仿真环境 <a class="header-anchor" href="#hitl-仿真环境" aria-label="Permalink to &quot;HITL 仿真环境&quot;">​</a></h2><p>硬件在环仿真（HITL）模式下标准的 PX4 固件在真实的硬件上运行。 The HITL Simulation Environment in documented in: <a href="./../simulation/hitl">HITL Simulation</a>.</p><h2 id="操纵杆-手柄集成" tabindex="-1">操纵杆／手柄集成 <a class="header-anchor" href="#操纵杆-手柄集成" aria-label="Permalink to &quot;操纵杆／手柄集成&quot;">​</a></h2><p><em>QGroundControl</em> desktop versions can connect to a USB Joystick/Gamepad and send its movement commands and button presses to PX4 over MAVLink. 相反，它将数据包路由到 &quot;本地主机&quot;。 If you don&#39;t have a joystick you can alternatively control the vehicle using QGroundControl&#39;s onscreen virtual thumbsticks.</p><p>For setup information see the <em>QGroundControl User Guide</em>:</p><ul><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/joystick.html" target="_blank" rel="noreferrer">Joystick Setup</a></li><li><a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/settings_view/virtual_joystick.html" target="_blank" rel="noreferrer">Virtual Joystick</a></li></ul><h2 id="相机模拟" tabindex="-1">相机模拟 <a class="header-anchor" href="#相机模拟" aria-label="Permalink to &quot;相机模拟&quot;">​</a></h2><p>PX4 supports capture of both still images and video from within the <a href="./../sim_gazebo_classic/">Gazebo Classic</a> simulated environment. This can be enabled/set up as described in <a href="./../sim_gazebo_classic/#video-streaming">Gazebo Glassic &gt; Video Streaming</a>.</p><p>The simulated camera is a gazebo classic plugin that implements the <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">MAVLink Camera Protocol</a> . PX4 connects/integrates with this camera in <em>exactly the same way</em> as it would with any other MAVLink camera:</p><ol><li><a href="./../advanced_config/parameter_reference#TRIG_INTERFACE">TRIG_INTERFACE</a> must be set to <code>3</code> to configure the camera trigger driver for use with a MAVLink camera<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In this mode the driver just sends a <a href="https://mavlink.io/en/messages/common.html#CAMERA_TRIGGER" target="_blank" rel="noreferrer">CAMERA_TRIGGER</a> message whenever an image capture is requested. For more information see <a href="./../camera/fc_connected_camera">Cameras Connected to Flight Controller Outputs</a>.</p></div></li></ol><p>::: 2. PX4 必须在 GCS 和（模拟器）MAVLink Camera 之间转发所有摄像机命令。 You can do this by starting <a href="./../modules/modules_communication#mavlink">MAVLink</a> with the <code>-f</code> flag as shown, specifying the UDP ports for the new connection.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14558</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14530</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> camera</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>More than just the camera MAVLink messages will be forwarded, but the camera will ignore those that it doesn&#39;t consider relevant.</p></div><p>The same approach can be used by other simulators to implement camera support.</p><h2 id="在远程服务器上运行仿真" tabindex="-1">在远程服务器上运行仿真 <a class="header-anchor" href="#在远程服务器上运行仿真" aria-label="Permalink to &quot;在远程服务器上运行仿真&quot;">​</a></h2><p>It is possible to run the simulator on one computer, and access it from another computer on the same network (or on another network with appropriate routing). This might be useful, for example, if you want to test a drone application running on real companion computer hardware running against a simulated vehicle.</p><p>This does not work &quot;out of the box&quot; because PX4 does not route packets to external interfaces by default (in order to avoid spamming the network and different simulations interfering with each other). Instead it routes traffic internally - to &quot;localhost&quot;.</p><p>There are a number of ways to make the UDP packets available on external interfaces, as outlined below.</p><h3 id="启用-mav-broadcast" tabindex="-1">启用 MAV_BROADCAST <a class="header-anchor" href="#启用-mav-broadcast" aria-label="Permalink to &quot;启用 MAV_BROADCAST&quot;">​</a></h3><p>The <a href="https://github.com/mavlink-router/mavlink-router" target="_blank" rel="noreferrer">mavlink-router</a> can be used to route packets from localhost to an external interface.</p><p>To route packets between SITL running on one computer (sending MAVLink traffic to localhost on UDP port 14550), and QGC running on another computer (e.g. at address <code>10.73.41.30</code>) you could:</p><ul><li><p>Start <em>mavlink-router</em> with the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink-routerd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 10.73.41.30:14550</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:14550</span></span></code></pre></div></li><li><p>Use a <em>mavlink-router</em> conf file.</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[UdpEndpoint QGC]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Normal</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 10.73.41.30</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 14550</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[UdpEndpoint SIM]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Eavesdropping</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 14550</span></span></code></pre></div></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>More information about <em>mavlink-router</em> configuration can be found <a href="https://github.com/mavlink-router/mavlink-router#running" target="_blank" rel="noreferrer">here</a>.</p></div><h3 id="使用-mavlink-路由器" tabindex="-1">使用 MAVLink 路由器 <a class="header-anchor" href="#使用-mavlink-路由器" aria-label="Permalink to &quot;使用 MAVLink 路由器&quot;">​</a></h3><p>The <a href="./../modules/modules_communication#mavlink_usage">mavlink module</a> routes to <em>localhost</em> by default, but you can enable UDP broadcasting of heartbeats using its <code>-p</code> option. Any remote computer on the network can then connect to the simulator by listening to the appropriate port (i.e. 14550 for <em>QGroundControl</em>).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>UDP broadcasting provides a simple way to set up the connection when there is only one simulation running on the network. Do not use this approach if there are multiple simulations running on the network (you might instead <a href="#enable-streaming-to-specific-address">publish to a specific address</a>).</p></div><p>This should be done in an appropriate configuration file where <code>mavlink start</code> is called. For example: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink" target="_blank" rel="noreferrer">/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink</a>.</p><h3 id="修改外部广播的配置" tabindex="-1">修改外部广播的配置 <a class="header-anchor" href="#修改外部广播的配置" aria-label="Permalink to &quot;修改外部广播的配置&quot;">​</a></h3><p>The <a href="./../modules/modules_communication#mavlink_usage">mavlink module</a> routes to <em>localhost</em> by default, but you can specify an external IP address to stream to using its <code>-t</code> option. The specified remote computer can then connect to the simulator by listening to the appropriate port (i.e. 14550 for <em>QGroundControl</em>).</p><p>This should be done in various configuration files where <code>mavlink start</code> is called. For example: <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink" target="_blank" rel="noreferrer">/ROMFS/px4fmu_common/init.d-posix/px4-rc.mavlink</a>.</p><h3 id="ssh-通道" tabindex="-1">SSH 通道 <a class="header-anchor" href="#ssh-通道" aria-label="Permalink to &quot;SSH 通道&quot;">​</a></h3><p>SSH tunneling is a flexible option because the simulation computer and the system using it need not be on the same network.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You might similarly use VPN to provide a tunnel to an external interface (on the same network or another network).</p></div><p>One way to create the tunnel is to use SSH tunneling options. The tunnel itself can be created by running the following command on <em>localhost</em>, where <code>remote.local</code> is the name of a remote computer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 14551:localhost:14551</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote.local</span></span></code></pre></div><p>The UDP packets need to be translated to TCP packets so they can be routed over SSH. The <a href="https://en.wikipedia.org/wiki/Netcat" target="_blank" rel="noreferrer">netcat</a> utility can be used on both sides of the tunnel - first to convert packets from UDP to TCP, and then back to UDP at the other end.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>QGC must be running before executing <em>netcat</em>.</p></div><p>On the <em>QGroundControl</em> computer, UDP packet translation may be implemented by running following commands:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfifo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tcp2udp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lvp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14551</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tcp2udp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14550</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/tcp2udp</span></span></code></pre></div><p>On the simulator side of the SSH tunnel, the command is:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkfifo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/udp2tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lvup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14550</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/udp2tcp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> netcat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14551</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/udp2tcp</span></span></code></pre></div><p>The port number <code>14550</code> is valid for connecting to QGroundControl or another GCS, but should be adjusted for other endpoints (e.g. developer APIs etc.).</p><p>The tunnel may in theory run indefinitely, but <em>netcat</em> connections may need to be restarted if there is a problem.</p><p>The <a href="https://raw.githubusercontent.com/ThunderFly-aerospace/sitl_gazebo/autogyro-sitl/scripts/QGC_remote_connect.bash" target="_blank" rel="noreferrer">QGC_remote_connect.bash</a> script can be run on the QGC computer to automatically setup/run the above instructions. The simulation must already be running on the remote server, and you must be able to SSH into that server.</p>`,107)])])}const b=i(r,[["render",l]]);export{g as __pageData,b as default};
